//! The content test vectors (PROTOCOL §13): each message is built here from the Rust types and
//! written by hand as protobuf JSON in `vectors/v1/vectors.json` (generated by
//! `vectors/make_json.py`); both must give the same bytes. This test checks the Rust side;
//! `tools/content-vectors` checks the JSON side with an independent protobuf compiler.
//!
//! `SONGBIRD_WRITE_VECTORS=1 cargo test -p songbird-content --test vectors` fills in the hex.
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing,
    clippy::too_many_lines,
    clippy::unnecessary_wraps,
    reason = "tests"
)]

use prost::Message as _;
use songbird_content::schema::{
    AttachmentPointer, BlockListSync, CallAnswer, CallEvent, CallHangup, CallHistorySync,
    CallMessage, CallOffer, CallSenderKey, ChatPolicy, ChatRef, ChatState, ChatStateSync,
    ContactCard, Content, DataMessage, Delete, Edit, EventCreate, GroupUpdate, LinkPreview,
    LocationPin, Message, MessageRef, Nudge, Pin, Plaintext, PollClose, PollCreate, PollVote,
    Quote, ReadMark, ReadSync, ReceiptMessage, RequestResponse, Rsvp, SentTranscript, SettingsSync,
    Span, StarredSync, StickerRef, SyncMessage, Text, TimerChange, TypingMessage, VoteHead,
    call_event, call_hangup, call_message, content::Body, data_message::Kind, group_update,
    receipt_message, request_response, rsvp, span, sync_message,
};

fn b(byte: u8, n: usize) -> Vec<u8> {
    vec![byte; n]
}

fn r(a: u8, m: u8) -> MessageRef {
    MessageRef {
        author: b(a, 16),
        message_id: b(m, 16),
    }
}

fn content(body: Body) -> Content {
    Content {
        version: 1,
        message_id: b(0x01, 16),
        sent_at_ms: 1_800_000_000_000,
        body: Some(body),
        ..Content::default()
    }
}

fn call(kind: Option<call_message::Kind>) -> Content {
    content(Body::Call(CallMessage {
        call_id: b(0x07, 16),
        kind,
    }))
}

fn data(kind: Kind) -> Content {
    data_in(kind, Vec::new(), 0)
}

fn data_in(kind: Kind, group_id: Vec<u8>, expire_timer_s: u32) -> Content {
    content(Body::Data(DataMessage {
        group_id,
        expire_timer_s,
        kind: Some(kind),
    }))
}

fn sync(kind: sync_message::Kind) -> Content {
    content(Body::Sync(SyncMessage { kind: Some(kind) }))
}

fn text(body: &str) -> Option<Text> {
    Some(Text {
        body: body.into(),
        spans: Vec::new(),
    })
}

fn account(byte: u8) -> Option<ChatRef> {
    Some(ChatRef {
        account: b(byte, 16),
        group_id: Vec::new(),
    })
}

