/// The "reaction" vector's encoding (used inside `sync_sent` and `plaintext_franked`).
fn reaction_bytes() -> Vec<u8> {
    data(Kind::Reaction(songbird_content::schema::Reaction {
        target: Some(r(0x22, 0x33)),
        emoji: "\u{1F44D}".into(),
        remove: false,
        counter: 7,
    }))
    .encode_to_vec()
}

/// The franked plaintext vector: the padded bytes and its commitment.
fn franked() -> (Vec<u8>, [u8; 32]) {
    let content = reaction_bytes();
    let commit = songbird_content::commitment(&[0x42; 32], &content);
    let plain = Plaintext {
        content,
        franking_key: b(0x42, 32),
        profile_key: Vec::new(),
    };
    (songbird_content::pad(&plain.encode_to_vec()), commit)
}

/// Accepting a request: the accept response, sharing the profile key 32 × `11` beside it.
fn accept_with_profile_key() -> Vec<u8> {
    let content = data_less_accept().encode_to_vec();
    let plain = Plaintext {
        content,
        franking_key: Vec::new(),
        profile_key: b(0x11, 32),
    };
    songbird_content::pad(&plain.encode_to_vec())
}

fn data_less_accept() -> Content {
    content(Body::RequestResponse(RequestResponse {
        action: request_response::Action::Accept.into(),
        chat: account(0x22),
    }))
}

fn file() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("vectors/v1/vectors.json")
}

#[test]
fn every_vector_matches_the_rust_types_byte_for_byte() {
    let path = file();
    let mut doc: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
    let ours = vectors();
    let write = std::env::var_os("SONGBIRD_WRITE_VECTORS").is_some();
    let list = doc["vectors"].as_array_mut().unwrap();
    assert_eq!(list.len(), ours.len() + 2, "every vector is in the file");
    for v in list.iter_mut() {
        let name = v["name"].as_str().unwrap().to_owned();
        let bytes = if name == "plaintext_franked" {
            franked().0
        } else if name == "plaintext_accept" {
            let p = accept_with_profile_key();
            assert_eq!(
                songbird_content::open(&p).unwrap().profile_key,
                Some([0x11; 32])
            );
            p
        } else {
            let c = &ours
                .iter()
                .find(|(n, _)| *n == name)
                .unwrap_or_else(|| panic!("no Rust vector {name}"))
                .1;
            // Every vector is valid content and decodes back to itself.
            songbird_content::validate::content(c).unwrap_or_else(|e| panic!("{name}: {e}"));
            let bytes = c.encode_to_vec();
            assert_eq!(&Content::decode(bytes.as_slice()).unwrap(), c, "{name}");
            bytes
        };
        if write {
            v["hex"] = serde_json::Value::String(hex::encode(&bytes));
        } else {
            assert_eq!(v["hex"].as_str().unwrap(), hex::encode(&bytes), "{name}");
        }
    }
    if write {
        let text = serde_json::to_string_pretty(&doc).unwrap();
        std::fs::write(&path, text + "\n").unwrap();
    }
}

#[test]
fn the_franked_plaintext_opens_and_its_commitment_verifies() {
    let (padded, commit) = franked();
    let o = songbird_content::open(&padded).unwrap();
    assert!(o.franking_matches(&commit));
    assert_eq!(o.content_bytes, reaction_bytes());
    // Its commitment, recomputed independently (Python's hmac):
    assert_eq!(
        hex::encode(commit),
        include_str!("../vectors/v1/plaintext_franked.commitment").trim()
    );
}
